//! [`AlphaAtlasManager`]: holds the CPU-side copy of the alpha values generated by sparse strips
//! rasterization, and handles their allocation and upload into a texture.
//!
//! The C++ manager keeps the `Recorder*` it was made with. Here, as in the other atlases of this
//! port ([`DrawAtlas`](crate::graphite::draw_atlas::DrawAtlas)), the methods that need the
//! recorder take it as an argument.
//!
//! The casts between `i32`, `u16` and `usize` below mirror the C++ arithmetic on byte counts, row
//! counts and slot numbers, which are all far below the narrow types' ranges.
#![allow(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::cast_possible_wrap
)]

use std::sync::Arc;

use skia_rust_core::alpha_type::AlphaType;
use skia_rust_core::image_info::ColorInfo;
use skia_rust_core::rect::IRect;
use skia_rust_core::size::ISize;

use crate::gpu::gpu_types::{Budgeted, Mipmapped, Renderable};
use crate::graphite::draw_context::DrawContext;
use crate::graphite::geom::end_caps::EndCaps;
use crate::graphite::recorder::Recorder;
use crate::graphite::sparse_strips::config::SparseStripConfig;
use crate::graphite::task::upload_task::{MipLevel, UploadSource};
use crate::graphite::texture_format::read_swizzle_for_color_type;
use crate::graphite::texture_proxy::TextureProxy;
use crate::graphite::texture_proxy_view::TextureProxyView;

/// `kMaxTexturePages` as an array length.
const K_PAGES: usize = SparseStripConfig::K_MAX_TEXTURE_PAGES as usize;

/// `kInvalidSlot`.
// Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.h#L84 (chrome/m156)
const K_INVALID_SLOT: i32 = -1;

/// The struct backing the manager's pages. Note, the struct contains `alpha_buffer`, which holds
/// the cpu-side data for the page (e.g. a single upload).
// Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.h#L87-L103 (chrome/m156)
#[derive(Debug, Default)]
struct TexturePage {
    /// `fTexture`.
    texture: Option<Arc<TextureProxy>>,
    /// `fRowCount`.
    row_count: i32,
    /// `fCapacityBytes`.
    capacity_bytes: i32,
    /// `fUsedBytes`.
    used_bytes: i32,
    /// `fUploadedRows`.
    uploaded_rows: i32,
    /// `fAlphaBuffer`.
    alpha_buffer: Vec<u8>,
}

impl TexturePage {
    /// `isValid()`.
    fn is_valid(&self) -> bool {
        self.texture.is_some()
    }

    /// `reset()`.
    fn reset(&mut self) {
        self.texture = None;
        self.row_count = 0;
        self.capacity_bytes = 0;
        self.used_bytes = 0;
        self.uploaded_rows = 0;
        self.alpha_buffer.clear();
    }
}

/// `append(n)` of an `SkTDArray<uint8_t>`: grows `buffer` by `n` bytes and returns them.
fn append(buffer: &mut Vec<u8>, n: i32) -> &mut [u8] {
    let start = buffer.len();
    buffer.resize(start + n as usize, 0);
    &mut buffer[start..]
}

/// Holds the cpu-side copy of alpha values generated by sparse strips rasterization, and handles
/// their allocation and upload into a texture.
///
/// Currently, the manager uses a two page system; when the first page is exhausted, the second
/// page is created with double the allocation. Uploads occur when the drawContext flushes; if two
/// pages are active at flush time, the older page is retired, and the larger page takes its place
/// as the initial page.
// Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.h#L32-L125 (chrome/m156)
#[doc(alias = "skgpu::graphite::AlphaAtlasManager")]
#[derive(Debug)]
pub struct AlphaAtlasManager {
    pages: [TexturePage; K_PAGES],

    /// Spillover memory and tracking for when all texture pages are exhausted. Only used when on
    /// the `kNullSlot`.
    null_buffer: Vec<u8>,
    null_buffer_used_bytes: i32,

    /// The slot of the texture page whose alpha buffer is currently being appended to. Should
    /// always be n < `kMaxTexturePages`.
    active_slot: i32,
    /// The slot of the last non-null texture page which was appended to.
    last_gpu_slot: i32,
    /// The slot of the last non-null texture page which was retired. Is only populated in null
    /// caps scenario, invalid otherwise.
    last_retired_slot: i32,
    next_page_row_count: i32,
}

impl Default for AlphaAtlasManager {
    fn default() -> Self {
        Self::new()
    }
}

impl AlphaAtlasManager {
    /// `kNullSlot`.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.h#L47 (chrome/m156)
    pub const K_NULL_SLOT: u16 = SparseStripConfig::K_MAX_TEXTURE_PAGES as u16;

    /// `AlphaAtlasManager(recorder)`.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L20-L26 (chrome/m156)
    #[must_use]
    pub fn new() -> Self {
        Self {
            pages: [TexturePage::default(), TexturePage::default()],
            null_buffer: Vec::new(),
            null_buffer_used_bytes: 0,
            active_slot: 0,
            last_gpu_slot: 0,
            last_retired_slot: K_INVALID_SLOT,
            next_page_row_count: SparseStripConfig::K_INITIAL_ATLAS_ROWS,
        }
    }

    /// `createPageInSlot(slot, minRequiredBytes)`.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L28-L73 (chrome/m156)
    fn create_page_in_slot(
        &mut self,
        recorder: &Recorder,
        slot: i32,
        min_required_bytes: i32,
    ) -> bool {
        debug_assert!(slot < SparseStripConfig::K_MAX_TEXTURE_PAGES);
        debug_assert!(!self.pages[slot as usize].is_valid());

        let mut rows = self.next_page_row_count;
        if min_required_bytes > 0 {
            let needed_rows = (min_required_bytes + SparseStripConfig::K_ATLAS_WIDTH_BYTES - 1)
                / SparseStripConfig::K_ATLAS_WIDTH_BYTES;
            if needed_rows > SparseStripConfig::K_MAX_ATLAS_ROWS {
                return false;
            }
            rows = rows.max(needed_rows);
        }
        rows = rows.min(SparseStripConfig::K_MAX_ATLAS_ROWS);

        let rp = recorder.priv_();
        let caps = rp.caps();
        let info = caps.get_default_sampled_texture_info(
            SparseStripConfig::K_COLOR_TYPE,
            Mipmapped::No,
            rp.is_protected(),
            Renderable::No,
        );
        let proxy = {
            let mut resource_provider = rp
                .resource_provider()
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            TextureProxy::make(
                caps.as_ref(),
                &mut resource_provider,
                ISize::new(SparseStripConfig::K_ATLAS_WIDTH, rows),
                &info,
                Budgeted::Yes,
                "AlphaAtlas",
            )
        };
        let Some(proxy) = proxy else {
            return false;
        };

        let page = &mut self.pages[slot as usize];
        page.texture = Some(proxy);
        page.row_count = rows;
        page.capacity_bytes = rows * SparseStripConfig::K_ATLAS_WIDTH_BYTES;
        page.used_bytes = 0;
        page.uploaded_rows = 0;
        page.alpha_buffer.clear();
        page.alpha_buffer.reserve(page.capacity_bytes as usize);

        // Double row count for the next created page, clamped to max atlas rows
        self.next_page_row_count = SparseStripConfig::K_MAX_ATLAS_ROWS.min(rows * 2);
        true
    }

    /// Returns the memory on the active texture page for writing `num_bytes` alphas.
    /// Overallocates the active page's buffer if the write exceeds `fCapacityBytes`.
    /// `None` if the request cannot be satisfied.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L75-L110 (chrome/m156)
    #[doc(alias = "requestAlphaSpace")]
    pub fn request_alpha_space(
        &mut self,
        recorder: &Recorder,
        num_bytes: i32,
    ) -> Option<&mut [u8]> {
        if num_bytes <= 0 || num_bytes > SparseStripConfig::K_MAX_ATLAS_BYTES {
            return None;
        }

        // 0. If already on the nullbuffer slot, append directly to it.
        if self.active_slot == i32::from(Self::K_NULL_SLOT) {
            return Some(append(&mut self.null_buffer, num_bytes));
        }

        // 1. Ensure current active slot has a valid page allocated
        debug_assert!(
            self.active_slot >= 0 && self.active_slot < SparseStripConfig::K_MAX_TEXTURE_PAGES
        );
        if !self.pages[self.active_slot as usize].is_valid()
            && !self.create_page_in_slot(recorder, self.active_slot, num_bytes)
        {
            return None;
        }

        // 2. If the active page is already full, proactively flip to the other slot
        if self.pages[self.active_slot as usize].used_bytes
            >= self.pages[self.active_slot as usize].capacity_bytes
        {
            let next_slot = self.active_slot ^ 1;

            // Both pages are in use, transition to null buffer.
            if self.pages[next_slot as usize].is_valid() {
                self.active_slot = i32::from(Self::K_NULL_SLOT);
                return Some(append(&mut self.null_buffer, num_bytes));
            }

            if !self.create_page_in_slot(recorder, next_slot, num_bytes) {
                return None;
            }
            self.active_slot = next_slot;
        }

        let active_page = &mut self.pages[self.active_slot as usize];
        self.last_gpu_slot = self.active_slot;
        Some(append(&mut active_page.alpha_buffer, num_bytes))
    }

    /// Finalizes the current boundary run.
    /// If the run straddled pages, allocates the next page and copies the overrun data. Returns a
    /// pair of `{alphaIndex, texPage}` on success, which indicate the page-local byte offset and
    /// atlas page index (0 or 1), respectively.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L112-L181 (chrome/m156)
    #[doc(alias = "finalizeRun")]
    pub fn finalize_run(&mut self, recorder: &Recorder) -> Option<(i32, u16)> {
        // Case 0: We are already on the nullbuffer
        if self.active_slot == i32::from(Self::K_NULL_SLOT) {
            debug_assert!(self.null_buffer.len() as i32 > self.null_buffer_used_bytes);
            let run_start_idx = self.null_buffer_used_bytes;
            self.null_buffer_used_bytes = self.null_buffer.len() as i32;
            return Some((run_start_idx, Self::K_NULL_SLOT));
        }

        let active_slot = self.active_slot as usize;
        if !self.pages[active_slot].is_valid() {
            return None;
        }

        debug_assert!(
            self.pages[active_slot].alpha_buffer.len() as i32 > self.pages[active_slot].used_bytes
        );
        let run_bytes =
            self.pages[active_slot].alpha_buffer.len() as i32 - self.pages[active_slot].used_bytes;

        // Case 1: Run completely fits in active page (no straddle)
        let run_start_idx = self.pages[active_slot].used_bytes;
        if self.pages[active_slot].alpha_buffer.len() as i32
            <= self.pages[active_slot].capacity_bytes
        {
            self.pages[active_slot].used_bytes = self.pages[active_slot].alpha_buffer.len() as i32;
            return Some((run_start_idx, active_slot as u16));
        }

        // Case 2: Run straddled the page boundary!
        let next_slot = self.active_slot ^ 1;
        if self.pages[next_slot as usize].is_valid() {
            // Both GPU slots are full! Switch to null buffer.
            // Currently this only occurs when all atlas pages have been exhausted, so fNullBuffer
            // is guaranteed to be empty at this point, making offset 0 (below) valid. If
            // fNullBuffer is ever reused or shared across draws in the future, this should return
            // the appended run's actual start offset (runStartIdx in fNullBuffer) instead.
            debug_assert_eq!(self.null_buffer.len(), 0);
            let overrun = self.pages[active_slot].alpha_buffer
                [run_start_idx as usize..(run_start_idx + run_bytes) as usize]
                .to_vec();
            append(&mut self.null_buffer, run_bytes).copy_from_slice(&overrun);

            // Trim overrun from activePage back to its committed size
            let used_bytes = self.pages[active_slot].used_bytes;
            self.pages[active_slot]
                .alpha_buffer
                .truncate(used_bytes as usize);

            // Switch active slot to kNullSlot
            self.active_slot = i32::from(Self::K_NULL_SLOT);
            self.null_buffer_used_bytes = self.null_buffer.len() as i32;
            return Some((0, Self::K_NULL_SLOT));
        }

        if !self.create_page_in_slot(recorder, next_slot, run_bytes) {
            return None;
        }

        // Append runBytes to newPage and copy the overrun data
        let overrun = self.pages[active_slot].alpha_buffer
            [run_start_idx as usize..(run_start_idx + run_bytes) as usize]
            .to_vec();
        append(&mut self.pages[next_slot as usize].alpha_buffer, run_bytes)
            .copy_from_slice(&overrun);

        // Trim overrun from activePage back to its committed size
        let used_bytes = self.pages[active_slot].used_bytes;
        self.pages[active_slot]
            .alpha_buffer
            .truncate(used_bytes as usize);

        // Switch active slot to nextSlot
        self.active_slot = next_slot;
        self.pages[next_slot as usize].used_bytes = run_bytes;
        Some((0, self.active_slot as u16))
    }

    /// `recordUploads(dc)`: uploads the rows of each page that have not been uploaded yet, and,
    /// when both pages are in use, retires the older one. `dc` may be `None`, which only does the
    /// bookkeeping.
    ///
    /// # Panics
    /// If a valid page has no texture, which `createPageInSlot` never leaves behind.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L183-L244 (chrome/m156)
    #[doc(alias = "recordUploads")]
    pub fn record_uploads(&mut self, mut dc: Option<&mut DrawContext>, recorder: &Recorder) {
        for page in &mut self.pages {
            if !page.is_valid() {
                continue;
            }

            let start_row = page.uploaded_rows;
            let total_used_rows = (page.used_bytes + SparseStripConfig::K_ATLAS_WIDTH_BYTES - 1)
                / SparseStripConfig::K_ATLAS_WIDTH_BYTES;
            let pending_rows = total_used_rows - start_row;

            if pending_rows > 0 {
                debug_assert!(page.texture.is_some());
                let padded_size = total_used_rows * SparseStripConfig::K_ATLAS_WIDTH_BYTES;
                if (page.alpha_buffer.len() as i32) < padded_size {
                    let diff = padded_size - page.alpha_buffer.len() as i32;
                    append(&mut page.alpha_buffer, diff).fill(0);
                }

                if let Some(dc) = dc.as_deref_mut() {
                    let proxy = page.texture.clone().expect("a valid page has a texture");
                    let level = MipLevel {
                        pixels: Some(
                            &page.alpha_buffer
                                [(start_row * SparseStripConfig::K_ATLAS_WIDTH_BYTES) as usize..],
                        ),
                        row_bytes: SparseStripConfig::K_ATLAS_WIDTH_BYTES as usize,
                    };
                    let dst_rect = IRect::from_xywh(
                        0,
                        start_row,
                        SparseStripConfig::K_ATLAS_WIDTH,
                        pending_rows,
                    );

                    let read_swizzle = read_swizzle_for_color_type(
                        SparseStripConfig::K_COLOR_TYPE,
                        proxy.format(),
                    );
                    let proxy_view = TextureProxyView::new(Some(proxy), read_swizzle);
                    let src_color_info =
                        ColorInfo::new(SparseStripConfig::K_COLOR_TYPE, AlphaType::Premul, None);
                    let dst_color_info =
                        ColorInfo::new(SparseStripConfig::K_COLOR_TYPE, AlphaType::Premul, None);
                    let rp = recorder.priv_();
                    let source = UploadSource::make(
                        rp.caps().as_ref(),
                        &proxy_view,
                        &src_color_info,
                        &dst_color_info,
                        std::slice::from_ref(&level),
                        dst_rect,
                    );
                    dc.record_upload(&rp, &source, None);
                }

                page.uploaded_rows = total_used_rows;
                page.used_bytes = padded_size;
            }
        }

        // At flush time, retire the older GPU slot if both were valid.
        if self.pages[0].is_valid() && self.pages[1].is_valid() {
            // If we're on the null texture, the active slot is instead the last gpu slot.
            let active_gpu_slot = if self.active_slot < SparseStripConfig::K_MAX_TEXTURE_PAGES {
                self.active_slot
            } else {
                self.last_gpu_slot
            };
            let old_slot = active_gpu_slot ^ 1;
            debug_assert!(self.pages[old_slot as usize].is_valid());
            self.pages[old_slot as usize].reset();
            self.last_retired_slot = old_slot;
        }
    }

    /// `resolveNullCaps(ends)`: moves the alphas of the caps that overflowed into the null buffer
    /// into the pages that were retired at flush time. Returns whether any cap made progress.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L246-L329 (chrome/m156)
    #[doc(alias = "resolveNullCaps")]
    pub fn resolve_null_caps(&mut self, recorder: &Recorder, ends: &mut EndCaps) -> bool {
        debug_assert!(ends.has_null_caps() && !self.null_buffer.is_empty());
        let first_null = ends.first_null_cap_index();
        debug_assert!(first_null >= 0 && (first_null as usize) < ends.caps().len());

        // Use the slot that was freed at flush time
        if self.last_retired_slot == K_INVALID_SLOT {
            return false;
        }
        debug_assert!(!self.pages[self.last_retired_slot as usize].is_valid());
        let mut current_slot = self.last_retired_slot;

        // Allocate currentSlot up to max capacity
        let null_bytes =
            self.null_buffer.len() as i32 - ends.caps()[first_null as usize].alpha_index;
        if !self.create_page_in_slot(
            recorder,
            current_slot,
            null_bytes.min(SparseStripConfig::K_MAX_ATLAS_BYTES),
        ) {
            return false;
        }
        self.last_retired_slot = K_INVALID_SLOT;

        // Copy the data from the null buffer into the new texture pages.
        let mut next_null = first_null;
        let round_start_cap = first_null;
        let cap_count = ends.caps().len() as i32;
        while next_null < cap_count {
            let alpha_index = ends.caps()[next_null as usize].alpha_index;
            let cap_bytes = i32::from(ends.caps()[next_null as usize].width)
                * i32::from(SparseStripConfig::K_TILE_HEIGHT);
            debug_assert!(cap_bytes > 0);

            // If the run exceeds the current slot, try to instantiate the other page
            if self.pages[current_slot as usize].used_bytes + cap_bytes
                > self.pages[current_slot as usize].capacity_bytes
            {
                let other_slot = current_slot ^ 1;
                if !self.pages[other_slot as usize].is_valid()
                    || self.pages[other_slot as usize].used_bytes == 0
                {
                    if self.pages[other_slot as usize].is_valid() {
                        self.pages[other_slot as usize].reset();
                    }
                    let remaining_bytes = self.null_buffer.len() as i32 - alpha_index;
                    if !self.create_page_in_slot(
                        recorder,
                        other_slot,
                        remaining_bytes.min(SparseStripConfig::K_MAX_ATLAS_BYTES),
                    ) {
                        break;
                    }
                    if self.pages[other_slot as usize].used_bytes + cap_bytes
                        > self.pages[other_slot as usize].capacity_bytes
                    {
                        self.pages[other_slot as usize].reset();
                        break;
                    }
                    current_slot = other_slot;
                } else {
                    // Both slots have been filled for this round
                    break;
                }
            }

            let page = &mut self.pages[current_slot as usize];
            // The C++ `memcpy`s `capBytes` from the null buffer without checking its size (a cap
            // of a test, e.g. `SparseStrips_AtlasNullBufferAndNullCaps`, can be larger than what
            // was written for it, and the copy then reads the spare capacity of the array). The
            // bytes past the end of the null buffer are zeros here.
            let copy_end = ((alpha_index + cap_bytes) as usize).min(self.null_buffer.len());
            let old_len = page.alpha_buffer.len();
            page.alpha_buffer
                .extend_from_slice(&self.null_buffer[alpha_index as usize..copy_end]);
            page.alpha_buffer.resize(old_len + cap_bytes as usize, 0);
            let cap = &mut ends.caps_mut()[next_null as usize];
            cap.tex_page = current_slot as u16;
            cap.alpha_index = page.used_bytes;
            page.used_bytes += cap_bytes;
            next_null += 1;
        }

        if next_null == round_start_cap {
            // Made zero progress
            return false;
        }

        ends.set_draw_start_index(round_start_cap);

        if next_null == cap_count {
            // We're done, no more rounds of flushing are necessary.
            ends.clear_null_caps();
            self.null_buffer.clear();
            self.null_buffer_used_bytes = 0;
        } else {
            ends.set_first_null_cap_index(next_null);
        }

        self.populate_proxies(ends);
        self.active_slot = current_slot;
        self.last_gpu_slot = current_slot;
        true
    }

    /// `populateProxies(ends)`: sets the proxies of `ends` to the pages of the manager.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L331-L346 (chrome/m156)
    #[doc(alias = "populateProxies")]
    pub fn populate_proxies(&self, ends: &mut EndCaps) {
        let mut start_slot = 0;
        while start_slot < K_PAGES && !self.pages[start_slot].is_valid() {
            start_slot += 1;
        }
        debug_assert!(start_slot < K_PAGES);

        let mut last_valid = self.pages[start_slot].texture.clone();
        for i in 0..K_PAGES {
            let slot = (start_slot + i) % K_PAGES;
            if self.pages[slot].is_valid() {
                last_valid.clone_from(&self.pages[slot].texture);
            }
            ends.set_proxy(slot, last_valid.clone());
        }
    }

    /// `freeGpuResources()`.
    // Port of: src/gpu/graphite/sparse_strips/AlphaAtlasManager.cpp#L348-L358 (chrome/m156)
    #[doc(alias = "freeGpuResources")]
    pub fn free_gpu_resources(&mut self) {
        for page in &mut self.pages {
            page.reset();
        }
        self.null_buffer.clear();
        self.null_buffer_used_bytes = 0;
        self.active_slot = 0;
        self.last_gpu_slot = 0;
        self.last_retired_slot = K_INVALID_SLOT;
        self.next_page_row_count = SparseStripConfig::K_INITIAL_ATLAS_ROWS;
    }

    /// `numPages()`.
    #[doc(alias = "numPages")]
    #[must_use]
    pub fn num_pages(&self) -> usize {
        self.pages.iter().filter(|page| page.is_valid()).count()
    }

    /// `activePageRowCount()`.
    #[doc(alias = "activePageRowCount")]
    #[must_use]
    pub fn active_page_row_count(&self) -> i32 {
        if self.active_slot < SparseStripConfig::K_MAX_TEXTURE_PAGES
            && self.pages[self.active_slot as usize].is_valid()
        {
            self.pages[self.active_slot as usize].row_count
        } else {
            0
        }
    }

    /// `getPageProxy(index)`.
    #[doc(alias = "getPageProxy")]
    #[must_use]
    pub fn get_page_proxy(&self, index: usize) -> Option<Arc<TextureProxy>> {
        if index < K_PAGES && self.pages[index].is_valid() {
            self.pages[index].texture.clone()
        } else {
            None
        }
    }

    /// `getPageData(index)`: the alphas of a page, or of the null buffer for `kNullSlot`.
    #[doc(alias = "getPageData")]
    #[must_use]
    pub fn get_page_data(&self, index: usize) -> Option<&[u8]> {
        if index == usize::from(Self::K_NULL_SLOT) {
            return Some(&self.null_buffer);
        }
        if index < K_PAGES && self.pages[index].is_valid() {
            Some(&self.pages[index].alpha_buffer)
        } else {
            None
        }
    }

    /// `activeSlot()`.
    #[doc(alias = "activeSlot")]
    #[must_use]
    pub fn active_slot(&self) -> i32 {
        self.active_slot
    }

    /// `hasNullBuffer()`.
    #[doc(alias = "hasNullBuffer")]
    #[must_use]
    pub fn has_null_buffer(&self) -> bool {
        !self.null_buffer.is_empty()
    }
}
